    asm volatile("ldmatrix.sync.aligned.m8n8.x4.shared.b16 {%0,%1,%2,%3}, [%4];\n"
                 : "=r"(r[0]), "=r"(r[1]), "=r"(r[2]), "=r"(r[3]) : "r"(addr));
}

// Dump: out_u32[lane*4+j] = reg j of ldsm at (row_base, chunk16).
__global__ void dump_kernel(const __nv_bfloat16* q, uint32_t* out_u32,
                            int row_base, int chunk16) {
    __shared__ __nv_bfloat16 sq[16][128];
    const int lane = threadIdx.x & 31;
    const uint32_t bq = (uint32_t)__cvta_generic_to_shared(sq);
    for (int idx = threadIdx.x; idx < 16 * 128; idx += 32) {
        int r = idx / 128, c = idx % 128;
        uint32_t addr = swizzled_addr(bq, r, c / 8);
        *reinterpret_cast<__nv_bfloat16*>(addr + (c % 8) * 2) = q[r * 128 + c];
    }
    __syncthreads();
    // also dump raw linear smem (no swizzle) for one row to verify writes
    if (lane == 0) out_u32[1024] = 0xdeadbeef;
    uint32_t rf[4];
    ldmatrix_x4(rf, bq, row_base, chunk16);
    #pragma unroll
    for (int j = 0; j < 4; ++j) out_u32[lane * 4 + j] = rf[j];
}

int main() {
    const int QROWS = 16, D = 128;
    __nv_bfloat16 *q; uint32_t *out;
    cudaMalloc(&q, QROWS * D * 2); cudaMalloc(&out, 1024 * 4 + 4);
    std::vector<__nv_bfloat16> hq(QROWS * D);
    for (int m = 0; m < QROWS; ++m)
        for (int d = 0; d < D; ++d)
            hq[m * D + d] = __float2bfloat16((float)(m * 100 + d));
    cudaMemcpy(q, hq.data(), QROWS * D * 2, cudaMemcpyHostToDevice);
    cudaMemset(out, 0, 1024 * 4 + 4);

    dump_kernel<<<1, 32>>>(q, out, 0, 0);
    CHK();
    std::vector<uint32_t> ho(1024 + 1);
    cudaMemcpy(ho.data(), out, (1024 + 1) * 4, cudaMemcpyDeviceToHost);
    // lane 0: expect reg0 = {q[0][0], q[0][1]} = 0x00010000 (bf16 pair)
    // lane 1: reg0 = {q[0][2], q[0][3]} = 0x00030002 ...
    for (int lane = 0; lane < 8; ++lane) {
        printf("lane %d: %08x %08x %08x %08x\n", lane,
               ho[lane*4], ho[lane*4+1], ho[lane*4+2], ho[lane*4+3]);
    }
    // check against expected: lane l reg0 = q[l/4][2*(l%4)..+1] as packed bf16
    int bad = 0;
    for (int lane = 0; lane < 32; ++lane) {
        for (int j = 0; j < 4; ++j) {
            int m, c0;
            if (j == 0) { m = lane >> 2; c0 = 2 * (lane & 3); }
            if (j == 1) { m = 8 + (lane >> 2); c0 = 2 * (lane & 3); }
            if (j == 2) { m = lane >> 2; c0 = 8 + 2 * (lane & 3); }
            if (j == 3) { m = 8 + (lane >> 2); c0 = 8 + 2 * (lane & 3); }
            uint32_t lo = __bfloat16_as_uint(hq[m * D + c0]);
            uint32_t hi = __bfloat16_as_uint(hq[m * D + c0 + 1]);
            uint32_t expect = lo | (hi << 16);
            if (ho[lane * 4 + j] != expect) {
                if (bad < 5)
                    printf("MISMATCH lane=%d j=%d got=%08x expect=%08x (m=%d c=%d)\n",
                           lane, j, ho[lane*4+j], expect, m, c0);
                bad++;
            }
        }
    }
    printf(bad ? "DUMP FAIL %d\n" : "DUMP OK\n", bad);
    return bad ? 1 : 0;
}

