// Tensor-core FlashAttention-style forward kernel (wmma m16n16k16, BF16).
// One block per (query tile, batch*head); BLOCK_M=64 query rows, 4 warps
// (16 rows each); K/V tiles of BLOCK_N=64 staged via cp.async double buffer.
// Supports MHA and GQA (kv_heads <= heads), causal and non-causal, any S.
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>
#include <cuda_bf16.h>
#include <mma.h>
#include <math.h>

namespace {

using namespace nvcuda;

constexpr int BLOCK_M = 64;
constexpr int BLOCK_N = 64;
constexpr int HEAD_DIM = 128;
constexpr int NUM_WARPS = 4;
constexpr int NUM_THREADS = NUM_WARPS * 32;
constexpr int PADDED_D = HEAD_DIM + 8;         // pad rows to avoid bank conflicts
constexpr int P_COLS = BLOCK_N + 8;
constexpr int TILE_ELEMS = BLOCK_N * PADDED_D;
constexpr int O_ELEMS = BLOCK_M * PADDED_D;
constexpr int P_SMEM = NUM_WARPS * 16 * P_COLS * 2;
constexpr int SMEM_BYTES = 4 * TILE_ELEMS * 2 + O_ELEMS * 2 + P_SMEM;

__device__ __forceinline__ void cp_async16(void* smem, const void* gmem) {
    uint32_t s = static_cast<uint32_t>(__cvta_generic_to_shared(smem));
    asm volatile("cp.async.cg.shared.global [%0], [%1], 16;\n" :: "r"(s), "l"(gmem));
}
__device__ __forceinline__ void cp_async_commit() { asm volatile("cp.async.commit_group;\n"); }
template<int N> __device__ __forceinline__ void cp_async_wait() {
    asm volatile("cp.async.wait_group %0;\n" :: "n"(N));
}

__device__ __forceinline__ void load_tile(const __nv_bfloat16* src,
                                          __nv_bfloat16* dst, int row0,
                                          int seq_len, bool zero_fill) {
    constexpr int CHUNKS = BLOCK_N * HEAD_DIM / 8;
    for (int i = threadIdx.x; i < CHUNKS; i += NUM_THREADS) {
        const int row = i / (HEAD_DIM / 8), col8 = i % (HEAD_DIM / 8);
        const int grow = row0 + row;
        __nv_bfloat16* s = dst + row * PADDED_D + col8 * 8;
        if (grow < seq_len) cp_async16(s, src + (long long)grow * HEAD_DIM + col8 * 8);
        else if (zero_fill) *reinterpret_cast<uint4*>(s) = make_uint4(0, 0, 0, 0);
    }
}

__device__ __forceinline__ float warp_max4(float v) {
    for (int off = 1; off < 4; off <<= 1) v = fmaxf(v, __shfl_xor_sync(0xffffffffu, v, off));
    return v;
}
__device__ __forceinline__ float warp_sum4(float v) {
    for (int off = 1; off < 4; off <<= 1) v += __shfl_xor_sync(0xffffffffu, v, off);
    return v;
}

__global__ void __launch_bounds__(NUM_THREADS, 1)
attention_fwd_kernel(const __nv_bfloat16* __restrict__ q,
                     const __nv_bfloat16* __restrict__ k,
                     const __nv_bfloat16* __restrict__ v,
                     __nv_bfloat16* __restrict__ out,
                     int seq_len, int kv_heads, float scale, bool causal)
{
    extern __shared__ char smem[];
    __nv_bfloat16* sK0 = reinterpret_cast<__nv_bfloat16*>(smem);
    __nv_bfloat16* sV0 = sK0 + TILE_ELEMS;
    __nv_bfloat16* sK1 = sV0 + TILE_ELEMS;
    __nv_bfloat16* sV1 = sK1 + TILE_ELEMS;
    __nv_bfloat16* sP = sV1 + TILE_ELEMS;
    __nv_bfloat16* sQO = sP + NUM_WARPS * 16 * P_COLS;

    const int m_tile = blockIdx.x, bh = blockIdx.y;
    const int b = bh / kv_heads;             // GQA: query head -> kv head
    const int h = bh % kv_heads;
    const long long qbase = (long long)bh * seq_len * HEAD_DIM;
    const long long kvbase = (long long)b * seq_len * HEAD_DIM;
    const int warp = threadIdx.x / 32, lane = threadIdx.x % 32;
    const int m0 = m_tile * BLOCK_M + warp * 16;
    const int m0b = m_tile * BLOCK_M;

    load_tile(q + qbase, sQO, m0b, seq_len, true);
    cp_async_commit(); cp_async_wait<0>(); __syncthreads();

    wmma::fragment<wmma::matrix_a, 16, 16, 16, __nv_bfloat16, wmma::row_major> q_frag[8];
    for (int kt = 0; kt < 8; ++kt)
        wmma::load_matrix_sync(q_frag[kt], sQO + warp * 16 * PADDED_D + kt * 16, PADDED_D);

    wmma::fragment<wmma::accumulator, 16, 16, 16, float> s_frag[4];
    wmma::fragment<wmma::accumulator, 16, 16, 16, float> o_frag[8];
    wmma::fragment<wmma::matrix_b, 16, 16, 16, __nv_bfloat16, wmma::col_major> k_frag;
    wmma::fragment<wmma::matrix_b, 16, 16, 16, __nv_bfloat16, wmma::row_major> v_frag;
    for (int i = 0; i < 8; ++i) wmma::fill_fragment(o_frag[i], 0.f);

    float m_prev[2] = {-INFINITY, -INFINITY};
    float l_prev[2] = {0.f, 0.f};

    const int n_tiles_total = (seq_len + BLOCK_N - 1) / BLOCK_N;
    const int n_tiles_block = causal ? min(n_tiles_total, (m0b + BLOCK_M - 1) / BLOCK_N + 1)
                                     : n_tiles_total;
    if (n_tiles_block > 0) {
        load_tile(k + kvbase, sK0, 0, seq_len, true);
        load_tile(v + kvbase, sV0, 0, seq_len, true);
        cp_async_commit();
    }

    for (int nt = 0; nt < n_tiles_block; ++nt) {
        const int buf = nt & 1;
        __nv_bfloat16* sK = buf ? sK1 : sK0;
        __nv_bfloat16* sV = buf ? sV1 : sV0;
        if (nt + 1 < n_tiles_block) {
            load_tile(k + kvbase, buf ? sK0 : sK1, (nt + 1) * BLOCK_N, seq_len, true);
            load_tile(v + kvbase, buf ? sV0 : sV1, (nt + 1) * BLOCK_N, seq_len, true);
            cp_async_commit();
        }
        if (nt + 1 < n_tiles_block) cp_async_wait<1>(); else cp_async_wait<0>();
        __syncthreads();
        const int kv0 = nt * BLOCK_N;

        for (int i = 0; i < 4; ++i) {
            const int kvc = kv0 + 16 * i;
            const bool full_mask = causal && (kvc > m0 + 15);
            const bool may_mask = causal && !full_mask && (kvc + 15 >= m0) && (kvc <= m0 + 15);
            __nv_bfloat16* Pw = sP + warp * (16 * P_COLS) + (16 * i) * P_COLS;
            for (int j = 0; j < 8; ++j) s_frag[i].x[j] = 0.f;
            if (full_mask) {
                for (int j = 0; j < 8; ++j) {
                    const int rr = ((j & 2) ? 8 : 0) + lane / 4;
                    const int cc = 2 * (lane % 4) + (j & 1) + ((j & 4) ? 8 : 0);
                    Pw[rr * P_COLS + cc] = __float2bfloat16(0.f);
                }
                continue;
            }
            for (int kt = 0; kt < 8; ++kt) {
                wmma::load_matrix_sync(k_frag, sK + (16 * i) * PADDED_D + kt * 16, PADDED_D);
                wmma::mma_sync(s_frag[i], q_frag[kt], k_frag, s_frag[i]);
            }
            for (int j = 0; j < 8; ++j) s_frag[i].x[j] *= scale;
            if (may_mask) {
                for (int j = 0; j < 8; ++j) {
                    const int rr = ((j & 2) ? 8 : 0) + lane / 4;
                    const int cc = 2 * (lane % 4) + (j & 1) + ((j & 4) ? 8 : 0);
                    if (kvc + cc > m0 + rr) s_frag[i].x[j] = -INFINITY;
                }
            }
            float tm0 = fmaxf(fmaxf(s_frag[i].x[0], s_frag[i].x[1]),
                              fmaxf(s_frag[i].x[4], s_frag[i].x[5]));
            float tm1 = fmaxf(fmaxf(s_frag[i].x[2], s_frag[i].x[3]),
                              fmaxf(s_frag[i].x[6], s_frag[i].x[7]));
            tm0 = warp_max4(tm0); tm1 = warp_max4(tm1);
            const float mn0 = fmaxf(m_prev[0], tm0), mn1 = fmaxf(m_prev[1], tm1);
            const float corr0 = __expf(m_prev[0] - mn0), corr1 = __expf(m_prev[1] - mn1);
            for (int o = 0; o < 8; ++o)
                for (int j = 0; j < 8; ++j)
                    o_frag[o].x[j] *= ((j & 2) ? corr1 : corr0);
            float ps0 = 0.f, ps1 = 0.f;
            for (int j = 0; j < 8; ++j) {
                const float p = __expf(s_frag[i].x[j] - ((j & 2) ? mn1 : mn0));
                s_frag[i].x[j] = p;
                if (j & 2) ps1 += p; else ps0 += p;
            }
            ps0 = warp_sum4(ps0); ps1 = warp_sum4(ps1);
            l_prev[0] = l_prev[0] * corr0 + ps0;
            l_prev[1] = l_prev[1] * corr1 + ps1;
            m_prev[0] = mn0; m_prev[1] = mn1;
            for (int j = 0; j < 8; ++j) {
                const int rr = ((j & 2) ? 8 : 0) + lane / 4;
                const int cc = 2 * (lane % 4) + (j & 1) + ((j & 4) ? 8 : 0);
                Pw[rr * P_COLS + cc] = __float2bfloat16(s_frag[i].x[j]);
            }
        }
        __syncthreads();

        wmma::fragment<wmma::matrix_a, 16, 16, 16, __nv_bfloat16, wmma::row_major> p_frag[4];
        for (int kc = 0; kc < 4; ++kc)
            wmma::load_matrix_sync(p_frag[kc], sP + warp * (16 * P_COLS) + 16 * kc, P_COLS);
        for (int ot8 = 0; ot8 < 8; ++ot8)
            for (int kc = 0; kc < 4; ++kc) {
                wmma::load_matrix_sync(v_frag, sV + (16 * kc) * PADDED_D + ot8 * 16, PADDED_D);
                wmma::mma_sync(o_frag[ot8], p_frag[kc], v_frag, o_frag[ot8]);
            }
        __syncthreads();
    }

    const float inv0 = 1.f / l_prev[0], inv1 = 1.f / l_prev[1];
    for (int ot8 = 0; ot8 < 8; ++ot8) {
        const int d0 = ot8 * 16;
        for (int j = 0; j < 8; ++j) {
            const int rr = ((j & 2) ? 8 : 0) + lane / 4;
            const int cc = 2 * (lane % 4) + (j & 1) + ((j & 4) ? 8 : 0);
            const int grow = m0 + rr;
            if (grow < seq_len)
                sQO[(grow - m0b) * PADDED_D + d0 + cc] =
                    __float2bfloat16(o_frag[ot8].x[j] * ((j & 2) ? inv1 : inv0));
        }
    }
    __syncthreads();
    constexpr int OUT_CHUNKS = BLOCK_M * HEAD_DIM / 8;
    for (int i = threadIdx.x; i < OUT_CHUNKS; i += NUM_THREADS) {
        const int row = i / (HEAD_DIM / 8), col8 = i % (HEAD_DIM / 8);
        const int grow = m0b + row;
        if (grow < seq_len)
            *reinterpret_cast<uint4*>(out + qbase + (long long)grow * HEAD_DIM + col8 * 8) =
                *reinterpret_cast<const uint4*>(sQO + row * PADDED_D + col8 * 8);
    }
}

}  // namespace

torch::Tensor attention_forward(torch::Tensor q, torch::Tensor k,
                                torch::Tensor v, bool causal)
{
    TORCH_CHECK(q.is_cuda() && k.is_cuda() && v.is_cuda(), "q/k/v must be CUDA tensors");
    TORCH_CHECK(q.scalar_type() == torch::kBFloat16 &&
                k.scalar_type() == torch::kBFloat16 &&
                v.scalar_type() == torch::kBFloat16, "q/k/v must be bfloat16");
    TORCH_CHECK(q.dim() == 4, "expected [B, H, S, D]");
    TORCH_CHECK(k.dim() == 4 && v.dim() == 4, "k/v must be [B, kv_heads, S, D]");
    TORCH_CHECK(q.size(0) == k.size(0) && q.size(2) == k.size(2) &&
                q.size(3) == k.size(3) && k.size(3) == HEAD_DIM,
                "shape mismatch");
    TORCH_CHECK(q.size(1) % k.size(1) == 0, "H must be a multiple of kv_heads");
    TORCH_CHECK(q.is_contiguous() && k.is_contiguous() && v.is_contiguous(),
                "q/k/v must be contiguous");

    const at::cuda::CUDAGuard guard(q.device());
    const int B = q.size(0), H = q.size(1), S = q.size(2);
    const int kv_heads = k.size(1);
    TORCH_CHECK((long long)B * H <= 65535, "B*H exceeds grid.y limit");

    auto out = torch::empty_like(q);
    const float scale = 1.0f / sqrtf((float)HEAD_DIM);
    dim3 grid((S + BLOCK_M - 1) / BLOCK_M, B * H);

    static bool attr_set = false;
    if (!attr_set) {
        cudaFuncSetAttribute(attention_fwd_kernel,
                             cudaFuncAttributeMaxDynamicSharedMemorySize, SMEM_BYTES);
        attr_set = true;
    }

    attention_fwd_kernel<<<grid, NUM_THREADS, SMEM_BYTES,
                           at::cuda::getCurrentCUDAStream()>>>(
        reinterpret_cast<const __nv_bfloat16*>(q.data_ptr()),
        reinterpret_cast<const __nv_bfloat16*>(k.data_ptr()),
        reinterpret_cast<const __nv_bfloat16*>(v.data_ptr()),
        reinterpret_cast<__nv_bfloat16*>(out.data_ptr()),
        S, kv_heads, scale, causal);
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return out;
}

// Tensor-core FlashAttention-style forward kernel (wmma m16n16k16, BF16).
// One block per (query tile, batch*head); BLOCK_M=64 query rows, 4 warps
// (16 rows each); K/V tiles of BLOCK_N=64 staged via cp.async double buffer.
// Supports MHA and GQA (kv_heads <= heads), causal and non-causal, any S.
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>
#include <cuda_bf16.h>
#include <mma.h>
#include <math.h>

namespace {

using namespace nvcuda;

constexpr int BLOCK_M = 64;
constexpr int BLOCK_N = 64;
constexpr int HEAD_DIM = 128;
constexpr int NUM_WARPS = 4;
constexpr int NUM_THREADS = NUM_WARPS * 32;
constexpr int PADDED_D = HEAD_DIM + 8;         // pad rows to avoid bank conflicts
constexpr int P_COLS = BLOCK_N + 8;
constexpr int TILE_ELEMS = BLOCK_N * PADDED_D;
constexpr int O_ELEMS = BLOCK_M * PADDED_D;
constexpr int P_SMEM = NUM_WARPS * 16 * P_COLS * 2;
constexpr int SMEM_BYTES = 4 * TILE_ELEMS * 2 + O_ELEMS * 2 + P_SMEM;

__device__ __forceinline__ void cp_async16(void* smem, const void* gmem) {
    uint32_t s = static_cast<uint32_t>(__cvta_generic_to_shared(smem));
    asm volatile("cp.async.cg.shared.global [%0], [%1], 16;\n" :: "r"(s), "l"(gmem));
}
__device__ __forceinline__ void cp_async_commit() { asm volatile("cp.async.commit_group;\n"); }
template<int N> __device__ __forceinline__ void cp_async_wait() {
    asm volatile("cp.async.wait_group %0;\n" :: "n"(N));
}

__device__ __forceinline__ void load_tile(const __nv_bfloat16* src,
                                          __nv_bfloat16* dst, int row0,
                                          int seq_len, bool zero_fill) {
    constexpr int CHUNKS = BLOCK_N * HEAD_DIM / 8;
    for (int i = threadIdx.x; i < CHUNKS; i += NUM_THREADS) {
        const int row = i / (HEAD_DIM / 8), col8 = i % (HEAD_DIM / 8);
        const int grow = row0 + row;
        __nv_bfloat16* s = dst + row * PADDED_D + col8 * 8;
        if (grow < seq_len) cp_async16(s, src + (long long)grow * HEAD_DIM + col8 * 8);
        else if (zero_fill) *reinterpret_cast<uint4*>(s) = make_uint4(0, 0, 0, 0);
    }
}

__device__ __forceinline__ float warp_max4(float v) {
    for (int off = 1; off < 4; off <<= 1) v = fmaxf(v, __shfl_xor_sync(0xffffffffu, v, off));
    return v;
}
__device__ __forceinline__ float warp_sum4(float v) {
    for (int off = 1; off < 4; off <<= 1) v += __shfl_xor_sync(0xffffffffu, v, off);
    return v;
}

__global__ void __launch_bounds__(NUM_THREADS, 1)
attention_fwd_kernel(const __nv_bfloat16* __restrict__ q,
                     const __nv_bfloat16* __restrict__ k,
                     const __nv_bfloat16* __restrict__ v,
                     __nv_bfloat16* __restrict__ out,
                     int seq_len, int kv_heads, float scale, bool causal)
{
    extern __shared__ char smem[];
    __nv_bfloat16* sK0 = reinterpret_cast<__nv_bfloat16*>(smem);
    __nv_bfloat16* sV0 = sK0 + TILE_ELEMS;
    __nv_bfloat16* sK1 = sV0 + TILE_ELEMS;
    __nv_bfloat16* sV1 = sK1 + TILE_ELEMS;
    __nv_bfloat16* sP = sV1 + TILE_ELEMS;
    __nv_bfloat16* sQO = sP + NUM_WARPS * 16 * P_COLS;

    const int m_tile = blockIdx.x, bh = blockIdx.y;
    const int b = bh / kv_heads;             // GQA: query head -> kv head
    const int h = bh % kv_heads;
    const long long qbase = (long long)bh * seq_len * HEAD_DIM;
    const long long kvbase = (long long)b * seq_len * HEAD_DIM;
    const int warp = threadIdx.x / 32, lane = threadIdx.x % 32;
    const int m0 = m_tile * BLOCK_M + warp * 16;
    const int m0b = m_tile * BLOCK_M;

    load_tile(q + qbase, sQO, m0b, seq_len, true);
    cp_async_commit(); cp_async_wait<0>(); __syncthreads();

    wmma::fragment<wmma::matrix_a, 16, 16, 16, __nv_bfloat16, wmma::row_major> q_frag[8];
    for (int kt = 0; kt < 8; ++kt)
        wmma::load_matrix_sync(q_frag[kt], sQO + warp * 16 * PADDED_D + kt * 16, PADDED_D);

    wmma::fragment<wmma::accumulator, 16, 16, 16, float> s_frag[4];
    wmma::fragment<wmma::accumulator, 16, 16, 16, float> o_frag[8];
    wmma::fragment<wmma::matrix_b, 16, 16, 16, __nv_bfloat16, wmma::col_major> k_frag;
    wmma::fragment<wmma::matrix_b, 16, 16, 16, __nv_bfloat16, wmma::row_major> v_frag;
    for (int i = 0; i < 8; ++i) wmma::fill_fragment(o_frag[i], 0.f);

    float m_prev[2] = {-INFINITY, -INFINITY};
    float l_prev[2] = {0.f, 0.f};

    const int n_tiles_total = (seq_len + BLOCK_N - 1) / BLOCK_N;
    const int n_tiles_block = causal ? min(n_tiles_total, (m0b + BLOCK_M - 1) / BLOCK_N + 1)
                                     : n_tiles_total;
    if (n_tiles_block > 0) {
        load_tile(k + kvbase, sK0, 0, seq_len, true);
        load_tile(v + kvbase, sV0, 0, seq_len, true);
        cp_async_commit();
    }

    for (int nt = 0; nt < n_tiles_block; ++nt) {
        const int buf = nt & 1;
        __nv_bfloat16* sK = buf ? sK1 : sK0;
        __nv_bfloat16* sV = buf ? sV1 : sV0;
        if (nt + 1 < n_tiles_block) {
            load_tile(k + kvbase, buf ? sK0 : sK1, (nt + 1) * BLOCK_N, seq_len, true);
            load_tile(v + kvbase, buf ? sV0 : sV1, (nt + 1) * BLOCK_N, seq_len, true);
            cp_async_commit();
        }
        if (nt + 1 < n_tiles_block) cp_async_wait<1>(); else cp_async_wait<0>();
        __syncthreads();
        const int kv0 = nt * BLOCK_N;

        for (int i = 0; i < 4; ++i) {
            const int kvc = kv0 + 16 * i;
            const bool full_mask = causal && (kvc > m0 + 15);
            const bool may_mask = causal && !full_mask && (kvc + 15 >= m0) && (kvc <= m0 + 15);
            __nv_bfloat16* Pw = sP + warp * (16 * P_COLS) + (16 * i) * P_COLS;
            for (int j = 0; j < 8; ++j) s_frag[i].x[j] = 0.f;
            if (full_mask) {
                for (int j = 0; j < 8; ++j) {
                    const int rr = ((j & 2) ? 8 : 0) + lane / 4;
                    const int cc = 2 * (lane % 4) + (j & 1) + ((j & 4) ? 8 : 0);
                    Pw[rr * P_COLS + cc] = __float2bfloat16(0.f);
                }
                continue;
            }
            for (int kt = 0; kt < 8; ++kt) {
                wmma::load_matrix_sync(k_frag, sK + (16 * i) * PADDED_D + kt * 16, PADDED_D);
                wmma::mma_sync(s_frag[i], q_frag[kt], k_frag, s_frag[i]);
            }
            for (int j = 0; j < 8; ++j) s_frag[i].x[j] *= scale;
            if (may_mask) {
                for (int j = 0; j < 8; ++j) {
                    const int rr = ((j & 2) ? 8 : 0) + lane / 4;
                    const int cc = 2 * (lane % 4) + (j & 1) + ((j & 4) ? 8 : 0);
                    if (kvc + cc > m0 + rr) s_frag[i].x[j] = -INFINITY;
                }
            }
            float tm0 = fmaxf(fmaxf(s_frag[i].x[0], s_frag[i].x[1]),
                              fmaxf(s_frag[i].x[4], s_frag[i].x[5]));
            float tm1 = fmaxf(fmaxf(s_frag[i].x[2], s_frag[i].x[3]),
                              fmaxf(s_frag[i].x[6], s_frag[i].x[7]));
            tm0 = warp_max4(tm0); tm1 = warp_max4(tm1);
            const float mn0 = fmaxf(m_prev[0], tm0), mn1 = fmaxf(m_prev[1], tm1);
            const float corr0 = __expf(m_prev[0] - mn0), corr1 = __expf(m_prev[1] - mn1);
            for (int o = 0; o < 8; ++o)
                for (int j = 0; j < 8; ++j)
                    o_frag[o].x[j] *= ((j & 2) ? corr1 : corr0);
            float ps0 = 0.f, ps1 = 0.f;
            for (int j = 0; j < 8; ++j) {
                const float p = __expf(s_frag[i].x[j] - ((j & 2) ? mn1 : mn0));
                s_frag[i].x[j] = p;
                if (j & 2) ps1 += p; else ps0 += p;
            }
            ps0 = warp_sum4(ps0); ps1 = warp_sum4(ps1);
            l_prev[0] = l_prev[0] * corr0 + ps0;
            l_prev[1] = l_prev[1] * corr1 + ps1;
            m_prev[0] = mn0; m_prev[1] = mn1;
            for (int j = 0; j < 8; ++j) {
                const int rr = ((j & 2) ? 8 : 0) + lane / 4;
                const int cc = 2 * (lane % 4) + (j & 1) + ((j & 4) ? 8 : 0);
                Pw[rr * P_COLS + cc] = __float2bfloat16(s_frag[i].x[j]);
            }
        }
        __syncthreads();

        wmma::fragment<wmma::matrix_a, 16, 16, 16, __nv_bfloat16, wmma::row_major> p_frag[4];
        for (int kc = 0; kc < 4; ++kc)
            wmma::load_matrix_sync(p_frag[kc], sP + warp * (16 * P_COLS) + 16 * kc, P_COLS);
        for (int ot8 = 0; ot8 < 8; ++ot8)
            for (int kc = 0; kc < 4; ++kc) {
                wmma::load_matrix_sync(v_frag, sV + (16 * kc) * PADDED_D + ot8 * 16, PADDED_D);
                wmma::mma_sync(o_frag[ot8], p_frag[kc], v_frag, o_frag[ot8]);
            }
        __syncthreads();
    }

    const float inv0 = 1.f / l_prev[0], inv1 = 1.f / l_prev[1];
    for (int ot8 = 0; ot8 < 8; ++ot8) {
        const int d0 = ot8 * 16;
        for (int j = 0; j < 8; ++j) {
            const int rr = ((j & 2) ? 8 : 0) + lane / 4;
            const int cc = 2 * (lane % 4) + (j & 1) + ((j & 4) ? 8 : 0);
            const int grow = m0 + rr;
            if (grow < seq_len)
                sQO[(grow - m0b) * PADDED_D + d0 + cc] =
                    __float2bfloat16(o_frag[ot8].x[j] * ((j & 2) ? inv1 : inv0));
        }
    }
    __syncthreads();
    constexpr int OUT_CHUNKS = BLOCK_M * HEAD_DIM / 8;
    for (int i = threadIdx.x; i < OUT_CHUNKS; i += NUM_THREADS) {
        const int row = i / (HEAD_DIM / 8), col8 = i % (HEAD_DIM / 8);
        const int grow = m0b + row;
        if (grow < seq_len)
            *reinterpret_cast<uint4*>(out + qbase + (long long)grow * HEAD_DIM + col8 * 8) =
                *reinterpret_cast<const uint4*>(sQO + row * PADDED_D + col8 * 8);
    }
}

}  // namespace

torch::Tensor attention_forward(torch::Tensor q, torch::Tensor k,
                                torch::Tensor v, bool causal)
{
    TORCH_CHECK(q.is_cuda() && k.is_cuda() && v.is_cuda(), "q/k/v must be CUDA tensors");
    TORCH_CHECK(q.scalar_type() == torch::kBFloat16 &&
                k.scalar_type() == torch::kBFloat16 &&
                v.scalar_type() == torch::kBFloat16, "q/k/v must be bfloat16");
    TORCH_CHECK(q.dim() == 4, "expected [B, H, S, D]");
    TORCH_CHECK(k.dim() == 4 && v.dim() == 4, "k/v must be [B, kv_heads, S, D]");
    TORCH_CHECK(q.size(0) == k.size(0) && q.size(2) == k.size(2) &&
                q.size(3) == k.size(3) && k.size(3) == HEAD_DIM,
                "shape mismatch");
    TORCH_CHECK(q.size(1) % k.size(1) == 0, "H must be a multiple of kv_heads");
    TORCH_CHECK(q.is_contiguous() && k.is_contiguous() && v.is_contiguous(),
                "q/k/v must be contiguous");

    const at::cuda::CUDAGuard guard(q.device());
    const int B = q.size(0), H = q.size(1), S = q.size(2);
    const int kv_heads = k.size(1);
    TORCH_CHECK((long long)B * H <= 65535, "B*H exceeds grid.y limit");

    auto out = torch::empty_like(q);
    const float scale = 1.0f / sqrtf((float)HEAD_DIM);
    dim3 grid((S + BLOCK_M - 1) / BLOCK_M, B * H);

    static bool attr_set = false;
    if (!attr_set) {
        cudaFuncSetAttribute(attention_fwd_kernel,
                             cudaFuncAttributeMaxDynamicSharedMemorySize, SMEM_BYTES);
        attr_set = true;
    }

    attention_fwd_kernel<<<grid, NUM_THREADS, SMEM_BYTES,
                           at::cuda::getCurrentCUDAStream()>>>(
        reinterpret_cast<const __nv_bfloat16*>(q.data_ptr()),
        reinterpret_cast<const __nv_bfloat16*>(k.data_ptr()),
        reinterpret_cast<const __nv_bfloat16*>(v.data_ptr()),
        reinterpret_cast<__nv_bfloat16*>(out.data_ptr()),
        S, kv_heads, scale, causal);
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return out;
}

